  constructor;
  . intro h; exact Context.by_axm! h;
  . intro hp;
    suffices ∼φ ∉ Ω.theory by apply or_iff_not_imp_right.mp $ (either_mem Ω φ); assumption;
    by_contra hC;
    have hnp : Ω.theory *⊢[H]! ∼φ := Context.by_axm! hC;
    have := neg_mdp! hnp hp;
    have := Ω.consistent;
    contradiction;

